// ============================================================
// FUNCIÓN PRINCIPAL PARA SUBIR DATOS
// ============================================================
export default function SeedCaminos() {
  const handleSeed = async () => {
    try {
      // Subir capítulos
      for (const module of modules) {
        await setDoc(doc(db, 'caminos', module.id), module);
        console.log(`✅ Subido capítulo: ${module.title}`);
      }

      // Subir preguntas
      for (const q of questions) {
        await setDoc(doc(db, 'caminosTrivia', q.id), q);
      }
      console.log(`✅ Subidas ${questions.length} preguntas`);

      alert('🎉 Datos de Caminos Espirituales subidos correctamente.');
    } catch (error) {
      console.error('❌ Error:', error);
      alert('❌ Error al subir datos. Revisa la consola.');
    }
  };

  return (
    <button
      onClick={handleSeed}
      style={{
        padding: '12px 24px',
        background: '#6C63FF',
        color: 'white',
        border: 'none',
        borderRadius: '8px',
        cursor: 'pointer',
        fontSize: '1rem',
        marginBottom: '20px'
      }}
    >
      🌿 Subir Caminos Espirituales
    </button>
  );
}